    "# HỒ SƠ KHUNG STORY BIBLE — THỂ LOẠI TRINH THÁM NOIR / BÍ ẨN": "# STORY BIBLE STRUCTURAL FRAME — NOIR DETECTIVE / MYSTERY GENRE",
    "- Bối cảnh trung tâm: Tháp Đồng Hồ Đêm Mưa & Thành phố Cảng Sương Mù.": "- Central Setting: Rainy Night Clock Tower & Foggy Harbor City.",
    "- Quy luật thời gian: Chuông đồng chỉ rung khi có sự cố chuyển giao ký ức hoặc mở khóa tầng áp mái.": "- Time Rule: The bronze bell tolls only during memory-transfer anomalies or when unlocking the attic vault.",
    "- Giọng văn chủ đạo: Noir tiết chế, giàu chi tiết giác quan (mưa, đồng thau, giấy da, ánh đèn bão).": "- Dominant Tone: Restrained Noir rich in sensory details (rain, brass, parchment, storm lantern glow).",
    "=== TỔNG HỢP STORY BIBLE CHÍNH THỨC (BẢN MẪU GUEST MODE) ===": "=== OFFICIAL COMPILED STORY BIBLE (GUEST MODE SAMPLE) ===",
    "1. Bối cảnh & Luật ngầm:": "1. Worldbuilding & Hidden Rules:",
    "- Vụ hỏa hoạn 20 năm trước thực chất là màn che đậy cho cuộc thử nghiệm lưu trữ ký ức của Giáo sư Hoàng tại Tháp Đồng Hồ.": "- The fire 20 years ago was actually a cover-up for Professor Hoang's memory-archiving experiment at the Clock Tower.",
    "- Con số 13:00 trên mặt đồng hồ không chỉ thời gian mà là mã khóa cơ học nối lên gác chuông.": "- The 13:00 mark on the clock face is not a timestamp, but a mechanical cipher leading up to the belfry.",
    "2. Tuyến nhân vật chính:": "2. Main Cast of Characters:",
    "- Trần Minh Khôi (Chính): Thám tử lưu trữ, có vết sẹo cũ ở cổ tay trái, luôn giữ đồng hồ quả quýt vỡ kính.": "- Tran Minh Khoi (Protagonist): Archival detective with an old scar on his left wrist, always carrying a cracked pocket watch.",
    "- Lệ Băng (Đồng hành / Nghi phạm): Người giữ chùm chìa khóa đồng La Mã, nắm nửa sự thật về vụ hỏa hoạn.": "- Le Bang (Companion / Suspect): Keeper of the Roman-numeral bronze keys, holding half the truth about the fire.",
    "- Bé Miu (Nhân chứng bí ẩn): Xuất hiện trong hầm kín dù cửa khóa ngoài, cầm mảnh đồng khắc tên Giáo sư Hoàng.": "- Little Miu (Mysterious Witness): Appears inside the locked basement holding a bronze shard engraved with Professor Hoang's name.",
    "- Giáo sư Hoàng (Phản diện giấu mặt): Tác giả chuỗi sổ cái bìa đen và cỗ máy đồng bộ xung chuông.": "- Professor Hoang (Hidden Antagonist): Creator of the six black-bound ledgers and the bell-pulse memory synchronizer.",
    "3. Mạch phục bút đang chạy:": "3. Active Foreshadowing Threads:",
    "- Chìa khóa thứ tư hình bán nguyệt úp ngược -> Mở két sắt tầng áp mái.": "- Fourth key with inverted crescent mark -> Unlocks the attic safe.",
    "- Vết thương cổ tay trái của Minh Khôi cộng hưởng với tần số chuông đồng.": "- Minh Khoi's left-wrist scar resonates with the bronze bell's frequency.",
    "Nhân vật chính (Thám tử lưu trữ)": "Protagonist (Archival Detective)",
    "Điềm tĩnh, quan sát tỉ mỉ chi tiết cơ học, ám ảnh công lý bị chôn vùi.": "Calm, meticulously observes mechanical details, haunted by buried justice.",
    "Ngắn gọn, sắc bén, dùng ngôi \"Tôi\" — gọi Lệ Băng bằng chức danh hoặc tên.": "Concise, sharp, speaks in first-person \"I\" — addresses Le Bang by title or name.",
    "Người giữ khóa Tháp Đồng Hồ": "Keeper of the Clock Tower Keys",
    "Lạnh lùng bên ngoài nhưng cố bảo vệ bằng chứng gốc trước thế lực giấu mặt.": "Cold on the outside, yet secretly safeguarding the original evidence from shadowy forces.",
    "Mỉa mai nhẹ, hay đặt câu hỏi ngược để dò thái độ.": "Lightly ironic, often answers with counter-questions to probe intentions.",
    "Nhân chứng bí ẩn": "Mysterious Witness",
    "Nhạy bén với âm thanh bánh răng, xuất hiện tại những nơi tưởng chừng kín bưng.": "Acutely sensitive to gear sounds, appearing inside seemingly sealed rooms.",
    "Ngây thơ nhưng câu nào cũng chứa ẩn ý cảnh báo.": "Innocent tone, yet every sentence carries a hidden warning.",
    "Phản diện giấu mặt": "Hidden Antagonist",
    "Lập dị, tôn sùng việc \"khắc thời gian vào đồng thau\".": "Eccentric, obsessed with \"engraving time into brass\".",
    "Trang trọng, học thuật qua các trang sổ cái để lại.": "Formal and scholarly across the surviving ledger pages.",
    "13:00 là mã khóa gác chuông chứ không phải giờ cháy": "13:00 is the belfry cipher code, not the time of the fire",
    "Lệ Băng, Giáo sư Hoàng (Minh Khôi chỉ mới suy ra ở Chương 3)": "Le Bang, Professor Hoang (Minh Khoi only deduced it in Chapter 3)",
    "Giới cảnh sát thành phố & nhân viên viện lưu trữ": "City police force & archival institute staff",
    "Đường thông gió bí mật sau giá sách tầng hầm nối thẳng xuống bờ sông": "Secret ventilation shaft behind the basement bookshelf leading straight to the riverbank",
    "Trần Minh Khôi và Lệ Băng": "Tran Minh Khoi and Le Bang",
    "Vết sẹo cổ tay trái của Minh Khôi là dấu tích của chiếc vòng đồng thử nghiệm đầu tiên": "Minh Khoi's left-wrist scar is the imprint of the first prototype bronze ring",
    "Giáo sư Hoàng, Lệ Băng": "Professor Hoang, Le Bang",
    "Trần Minh Khôi (cấm AI để lộ quá sớm trước Chương 5!)": "Tran Minh Khoi (AI is strictly forbidden from spoiling this before Chapter 5!)",
    "Chìa khóa thứ tư khắc vệt bán nguyệt úp ngược": "Fourth key engraved with an inverted crescent mark",
    "Trùng khớp mảnh giấy cháy dở tại viện lưu trữ, dùng mở két tầng áp mái.": "Matches the half-burned paper at the archive; unlocks the attic safe.",
    "Con búp bê thiếu một chiếc cúc mắt & mảnh đồng tên Giáo sư Hoàng": "Rag doll missing one button eye & bronze shard bearing Professor Hoang's name",
    "Cúc mắt bị rơi bên trong rãnh trượt cánh cửa thông gió bí mật.": "The missing button eye fell inside the sliding track of the secret ventilation door.",
    "Cổ tay trái của Minh Khôi nhói theo tần số chuông đồng": "Minh Khoi's left wrist throbs in sync with the bronze bell frequency",
    "Chứng minh Minh Khôi từng trực tiếp có mặt trong phòng máy năm xưa.": "Proves Minh Khoi was physically present inside the clockwork chamber years ago.",
    "Chương 2": "Chapter 2",
    "Chương 3": "Chapter 3",
    "Chương 4": "Chapter 4",
    "Trần Minh Khôi": "Tran Minh Khoi",
