    "Giáo sư Hoàng": "Professor Hoang",
    "một luồng điện chạy dọc sống lưng, ánh mắt phức tạp, thở dài một tiếng, khẽ nhếch môi, không khỏi cảm thán": "a jolt of electricity down the spine, complicated gaze, let out a sigh, curled lips slightly, could not help exclaiming",
    "một luồng điện chạy dọc sống lưng, thở dài một tiếng, ánh mắt phức tạp, khẽ nhếch môi tạo thành một vòng cung, không khỏi cảm thán trong lòng, trong lòng dâng lên một cảm giác khó tả, bầu không khí bỗng trở nên tĩnh lặng đến đáng sợ, nụ cười nửa miệng đầy ẩn ý": "a jolt of electricity down the spine, let out a sigh, complicated gaze, lips curled into a slight arc, could not help exclaiming inwardly, an indescribable feeling welled up inside, the atmosphere suddenly grew eerily silent, a half-smile full of hidden meaning",
