    "“Ánh đèn huỳnh quang nhấp nháy cắt ngang sống mũi hắn, hắt một vệt bóng xám dài xuống mặt bàn gỗ.”": "“The flickering fluorescent light sliced across the bridge of his nose, casting a long gray shadow onto the wooden table.”",
    "Hoảng hốt kìm nén": "Suppressed panic",
    "“Đầu ngón tay đang giữ quai tách khẽ khựng lại, làm gợn sóng nhỏ trong lòng chén trà sậm màu.”": "“The fingertips gripping the teacup handle paused slightly, sending a tiny ripple across the dark tea.”",
    "Cô độc / Lạnh lẽo đô thị": "Loneliness / Urban chill",
    "“Ánh neon từ biển hiệu đối diện rỉ qua khe rèm chớp, nhuộm xanh bệ cửa sổ ẩm sương.”": "“Neon light from the sign across the street bled through the blinds, tinting the mist-dampened windowsill blue.”",
    "Ngỡ ngàng sững sờ": "Stunned astonishment",
    "“Đồng tử mở to hơn bình thường một chút, phản chiếu nguyên vẹn ngọn lửa nhỏ đang rung trước gió.”": "“Pupils widened just a fraction more than usual, reflecting the tiny flame trembling in the wind intact.”",
    "Kiệt sức sau biến cố": "Exhaustion after an ordeal",
    "“Quầng thâm mờ dưới mi mắt khiến cái chớp mắt của cô chậm hơn bình thường nửa nhịp.”": "“Faint dark circles beneath her lashes slowed every blink by half a beat.”",
    "Cảnh giác tột độ": "Extreme vigilance",
    "“Ánh nhìn quét nhanh qua khe cửa khép hờ, dừng đúng hai giây ở vệt bùn mới in cạnh thảm chùi chân.”": "“Her gaze swept swiftly past the half-shut door, lingering for exactly two seconds on the fresh mud print beside the doormat.”",
    "🌦️ Bối Cảnh Thời Tiết & Ánh Sáng Điện Ảnh (Chèn Nhanh Mở Cảnh)": "🌦️ Cinematic Weather & Lighting Settings (Quick Scene Openers)",
    "🌧️ Mưa đêm & Đèn đường": "🌧️ Night Rain & Streetlights",
    "Chèn mở cảnh": "Insert scene opener",
    "Hạt mưa đập chéo vào mặt kính quán cà phê, kéo nhòe vệt đèn hậu đỏ rực bên kia đại lộ.": "Raindrops slanted against the café windowpane, smearing the crimson taillights across the boulevard.",
    "🌫️ Sương sớm vùng cao / Đà Lạt": "🌫️ Highland Morning Mist / Da Lat",
    "Lớp sương trắng bàng bạc vắt ngang hàng thông, thấm lạnh qua gấu áo len ngay khi cửa vừa hé.": "A silvery-white layer of mist draped across the pine trees, seeping chill through the hem of the sweater the moment the door cracked open.",
    "☀️ Trưa nắng gắt ngột ngạt": "☀️ Stifling Blazing Noon",
    "Mặt đường nhựa bốc hơi nóng hập hừ, ánh nắng chói chang khiến bóng đổ dưới chân co rút thành một chấm đen sắc lẹm.": "The asphalt shimmered with sweltering heat, and the glaring midday sun shrank the shadow beneath his feet into a razor-sharp black dot.",
    "🌃 Đêm mất điện / Ánh nến": "🌃 Blackout Night / Candlelight",
    "Bóng trần nhà rung rinh theo ngọn bấc đèn cầy mỗi lần có luồng gió lùa qua khe cửa gỗ mục.": "Shadows trembled across the ceiling in time with the candle wick every time a draft slipped through the rotting wooden door crack.",
    "🍂 Gió thu cuối chiều": "🍂 Late Afternoon Autumn Breeze",
    "Cơn gió se sắt cuốn theo mùi hoa sữa hăng hắc và tiếng lá khô lạo xạo lăn qua bậc thềm đá.": "A brisk chill breeze carried the pungent scent of milkwood blossoms and the rustle of dry leaves skittering across the stone steps.",
