    "Gặp nút khó bấm, lỗi hiển thị hoặc tính năng hoạt động chưa mượt? Bấm mở khung này để báo cho tác giả sửa nhanh nhất nhé.": "Found a hard-to-click button, visual glitch, or sluggish feature? Open this panel to let the author fix it as fast as possible.",
