    "Bấm nút Mở Google AI Studio ở Bước 1 để sao chép lại nguyên vẹn mã khóa bắt đầu bằng AIzaSy... hoặc AQ....": "Click Open Google AI Studio in Step 1 to copy the full key starting with AIzaSy... or AQ....",
    "Thử bấm Tự Động Kiểm Tra Bằng Gemini Flash-Lite khi kết nối mạng ổn định.": "Try clicking Auto-Verify with Gemini Flash-Lite while on a stable internet connection.",
    "Trong trường hợp viết dài vượt hạn mức API, dùng nút Copy Prompt Tổng sang Gemini Web hoặc đổi về Gemini Flash.": "For long writing sessions exceeding API quotas, use Copy Master Prompt to Gemini Web or switch to Gemini Flash.",
    "Chọn thư mục ổ cứng không nhận hoặc không thấy lưu tệp": "Local drive folder not recognized or files not saving",
    "Tạo một thư mục riêng ngoài Desktop hoặc ổ D (ví dụ D:\\TruyenCuaToi) rồi chọn lại.": "Create a dedicated folder outside Desktop or on drive D (e.g., D:\\TruyenCuaToi) and select it again.",
    "Bấm Cho phép chỉnh sửa tệp khi Chrome hoặc Edge hiện cửa sổ hỏi quyền.": "Click Allow file editing when Chrome or Edge prompts for permission.",
    "Kiểm tra tình trạng lưu ở nút Tự Lưu 3 Tầng tại góc trái thanh trên cùng.": "Check saving status on the 3-Tier Auto-Save button at the top-left of the header bar.",
    "Đang gõ văn bản hoặc nhấn Backspace thì trang bị tải lại": "Page reloads while typing text or pressing Backspace",
    "Luôn lưu thư mục truyện tách riêng khỏi thư mục mã nguồn HTML.": "Always keep your story folder separate from the HTML source code folder.",
    "Module 36 (Zero-Reload Save Shield) đang tự động chặn tín hiệu reload từ WebSocket và sự kiện form/navigation.": "Module 36 (Zero-Reload Save Shield) automatically blocks reload signals from WebSocket and form/navigation events.",
    "Bấm Kiểm tra Khiên Chống Reload ở cuối Tab 6 để xem số lượt tải lại đã được chặn an toàn.": "Click Check Anti-Reload Shield at the bottom of Tab 6 to see how many reloads have been safely blocked.",
    "Đóng cửa sổ báo lỗi": "Close bug report window",
    "Ví dụ: Thanh tiêu đề Tab 2, Nút lọc Nháp, Ô chọn Font Tab 5...": "Example: Tab 2 header bar, Draft filter button, Tab 5 Font selector...",
    "Mô tả điều bạn đã bấm hoặc gõ và điều sai lệch xảy ra (Ví dụ: Mình bấm lọc Nháp nhưng vẫn hiện cả chương Đã duyệt...)": "Describe what you clicked or typed and what went wrong (Example: I clicked the Draft filter, yet Approved chapters still appeared...)",
    "Ví dụ: Chữ vàng trên nền xám khó đọc, hai nút đè viền lên nhau, trang tự load lại về cổng kết nối...": "Example: Yellow text on gray background is hard to read, two buttons overlap borders, page reloads back to the entry gate...",
    "Đã nhúng sẵn kênh Google Sheet mặc định (chỉ điền nếu muốn ghi đè URL khác)": "Default Google Sheet channel is pre-embedded (only enter if overriding with another URL)",
    "Gõ từ khóa (API, thư mục, đè chữ, reload, markdown)...": "Type keywords (API, folder, overlap, reload, markdown)...",
    "👑 MODULE 35 · TÁC GIẢ SPOTLIGHT": "👑 MODULE 35 · AUTHOR SPOTLIGHT",
    "Ghi Công Tác Giả (Mai Hải Đăng — Bi) & Kết Nối": "Author Credits (Mai Hải Đăng — Bi) & Connect",
    "Lời tâm sự 3 ngày làm web cùng AI của tác giả, bảng ghi công nổi bật tự động cuộn & kênh liên hệ trực tiếp.": "The author's heartfelt story of building this web studio in 3 days with AI, auto-scrolling credits roll & direct contact channels.",
