    "✍️ TÁC GIẢ DUY NHẤT: MAI HẢI ĐĂNG": "✍️ SOLE AUTHOR: MAI HẢI ĐĂNG",
    "Nickname ở nhà: Bi": "Home nickname: Bi",
    "⚡ 3 ngày toàn tâm cùng AI": "⚡ 3 dedicated days with AI",
    "Vì sao là \"Bi's Novel Writing Studio\"?": "Why \"Bi's Novel Writing Studio\"?",
    "📬 Kênh Kết Nối Tác Giả:": "📬 Author Contact Channels:",
    "📋 Chép Gmail": "📋 Copy Gmail",
