    "Toàn bộ kiến trúc, giao diện, lập trình và kiểm thử đều do một mình tác giả Mai Hải Đăng thực hiện cùng AI.": "All architecture, UI design, coding, and testing were carried out solo by author Mai Hải Đăng alongside AI.",
