    "Thanh lọc văn phong AI thuần khiết, Cố vấn Mode 1 -> Mode 2 & Bộ 3 Module 34-35-36": "Pure AI prose purification, Mode 1 -> Mode 2 advisor & Module 34-35-36 trio",
    "Đưa nút Approve & Lock Draft sang bên trái thanh Tab 2 và chống chồng chữ tuyệt đối ở mọi độ rộng.": "Moved the Approve & Lock Draft button to the left of the Tab 2 bar and eliminated text overlap at all widths.",
    "Sửa bộ lọc chương Tab 2: bấm Nháp chỉ hiện Nháp, bấm Đã duyệt chỉ hiện Đã duyệt, bấm Tổng mới hiện tất cả.": "Fixed Tab 2 chapter filter: Draft shows only Drafts, Approved shows only Approved, and All shows everything.",
    "Xây dựng Bộ 5 Prompt mẫu chuyên sâu với thanh chỉ dẫn xám riêng cho từng Chế độ (Mode 2 mở đầu bằng dàn ý thô).": "Built 5 deep template Prompts with dedicated gray instruction bars per Mode (Mode 2 starts with a rough outline).",
    "Khi chạy Mode 1 mà Mode 2 chưa có gợi ý diễn biến, bật nhắc thân thiện với cụm \"Mode 2\" gạch chân bấm nhảy thẳng sang Mode 2.": "When running Mode 1 without plot suggestions from Mode 2, show a friendly reminder with an underlined \"Mode 2\" link to jump straight to Mode 2.",
    "Tự động dệt kết quả Mode 2 vào Prompt tổng hợp của Mode 1 để nối mạch truyện liền lạc.": "Automatically weaves Mode 2 output into Mode 1's Master Prompt for seamless story continuity.",
    "Cấm AI dùng ký tự thô (**, *, #, ---) trong 5 chế độ + Chatbot Bi, đồng thời lọc sạch văn bản đầu ra.": "Forbids AI from using raw symbols (**, *, #, ---) across all 5 modes + Bi Chatbot, and auto-cleans the output text.",
    "Khử nền trắng chói cho toàn bộ hộp chọn <select> ở Tab 5 sang chữ trắng trên nền tối #09090b.": "Removed glaring white backgrounds on all <select> dropdowns in Tab 5 in favor of white text on dark #09090b.",
    "Ra mắt Mod 34 (Báo lỗi người dùng), Mod 35 (Author Credits Mai Hải Đăng) và Mod 36 (Khiên Chống Reload mất chữ).": "Launched Mod 34 (User Bug Report), Mod 35 (Author Credits Mai Hải Đăng), and Mod 36 (Anti-Reload Text-Loss Shield).",
    "Phạm vi:": "Scope:",
    "🧭 4 Nguyên Tắc Cầm Tay Khi Mai Hải Đăng Xây Studio Này": "🧭 4 Guiding Principles Mai Hải Đăng Followed When Building This Studio",
    "✍️ Người xây dựng duy nhất:": "✍️ Sole Builder:",
    "Tìm tính năng hoặc module (vd: Tab 2, NotebookLM, Mod 36)...": "Search feature or module (e.g., Tab 2, NotebookLM, Mod 36)...",
    "💡 Chức năng này để giúp bạn đồng bộ trạng thái trang web và mọi công việc qua thiết bị khác thông qua tải file về máy sau đó bạn tự lấy máy khác tải về gói dữ liệu hoặc bạn kết nối tự động qua Google": "💡 This feature helps you sync your studio state and all work to another device by downloading a data package to transfer manually, or by connecting automatically via Google Drive.",
    "🗂️ Bước 1: Đặt Tên Thư Mục Kết Quả Làm Việc": "🗂️ Step 1: Name Your Workspace Output Folder",
    "Tên này sẽ được dùng để đặt tên file .ZIP khi tải về máy và tên Thư mục tạo trực tiếp trên Google Drive của bạn.": "This name will be used for the downloaded .ZIP filename and the folder created directly on your Google Drive.",
