    "✨ Gợi ý theo ngày": "✨ Suggest by date",
    "🔒 Bảo mật tuyệt đối: API Key Gemini & OAuth Token được tự động lọc bỏ khi đóng gói chia sẻ .ZIP.": "🔒 Absolute Security: Gemini API Key & OAuth Token are automatically stripped when packaging a shareable .ZIP.",
    "💾 Bước 2A: Tải Về Máy & Chuyển Dự Án Sang Thiết Bị Khác": "💾 Step 2A: Download Locally & Move Project to Another Device",
