    "☁️ Bước 2B: Tải Thẳng Lên Google Drive & Lấy Link Chia Sẻ": "☁️ Step 2B: Upload Directly to Google Drive & Get Share Link",
    "Tạo ngay thư mục chứa toàn bộ chương, Story Bible và gói .ZIP trên Google Drive cá nhân, kèm tùy chọn mở link chia sẻ nhanh.": "Instantly create a folder containing all chapters, Story Bible, and the .ZIP bundle on your personal Google Drive, with an option to enable quick link sharing.",
    "▾ Hướng Dẫn Tạo Key & Client ID": "▾ Guide: Create API Key & Client ID",
    "Tạo hoặc chọn một Project trên Google Cloud Console rồi nhấn Enable (Bật) cho Google Drive API để trình duyệt được phép tạo thư mục và tải tệp.": "Create or select a Project in Google Cloud Console and click Enable for the Google Drive API so your browser is permitted to create folders and upload files.",
    "Mở trang Bật Google Drive API ↗": "Open Enable Google Drive API page ↗",
    "Vào Credentials → Create Credentials → API Key. Bạn có thể dán Key vào ô bên dưới rồi bấm \"Xác thực Key\" để kiểm tra kết nối Drive + Gemini Flash-Lite.": "Go to Credentials → Create Credentials → API Key. Paste the Key into the field below and click \"Verify Key\" to test your Drive + Gemini Flash-Lite connection.",
    "Mở trang Credentials tạo API Key ↗": "Open Credentials to create API Key ↗",
    "Tại mục Credentials → Create Credentials → OAuth client ID → chọn Application type là Web application. Dán đúng Origin hiện tại (sao chép ở nút bên dưới) vào mục Authorized JavaScript origins.": "Under Credentials → Create Credentials → OAuth client ID → set Application type to Web application. Paste this exact current Origin (copied via the button below) into Authorized JavaScript origins.",
    "Mở OAuth Consent / Client ID ↗": "Open OAuth Consent / Client ID ↗",
    "Nhấn \"Đăng nhập Google (drive.file)\" — Studio chỉ xin quyền truy cập các tệp/thư mục do chính Studio vừa tạo, tuyệt đối không đọc tệp riêng tư khác trong Drive của bạn.": "Click \"Sign in with Google (drive.file)\" — Studio only requests access to files/folders it creates itself, and never reads other private files in your Drive.",
    "Authorized JavaScript Origin của trang này:": "Authorized JavaScript Origin for this page:",
    "http://localhost (Vui lòng chạy qua Local Server / HTTPS để dùng OAuth)": "http://localhost (Please run over Local Server / HTTPS to use OAuth)",
