    "Đóng gói toàn bộ Chương truyện, Story Bible, Nhân vật, Đầu ra 5 Chế độ AI và file khôi phục vào 1 tệp .ZIP chuẩn tải ngay về thiết bị.": "Package all story Chapters, Story Bible, Characters, 5-Mode AI outputs, and restore data into a single standard .ZIP file downloaded directly to your device.",
    "Chọn tệp .ZIP hoặc .JSON bạn đã tải từ máy cũ để khôi phục toàn bộ dự án sang máy mới ngay lập tức.": "Select the .ZIP or .JSON file downloaded from your old device to restore the entire project to a new device immediately.",
    "Dán AIza... (từ Google Cloud Credentials)": "Paste AIza... (from Google Cloud Credentials)",
