    "Đăng nhập tài khoản Google cá nhân trên trình duyệt (chỉ cấp quyền drive.file cho thư mục Studio tạo).": "Sign in to your personal Google account in the browser (grants drive.file permission only for folders created by Studio).",
    "Tạo thư mục theo tên bạn nhập trên Google Drive, tải lên toàn bộ bản thảo + tệp .ZIP và tạo link chia sẻ.": "Create a folder with your entered name on Google Drive, upload the entire manuscript + .ZIP file, and generate a share link.",
    "🎬 BƯỚC 1 / 2 • KẾT NỐI VIDEO YOUTUBE VÀO RẠP VIẾT TRUYỆN": "🎬 STEP 1 / 2 • CONNECT YOUTUBE VIDEO TO THE WRITING THEATER",
    "Hướng Dẫn Copy Link YouTube (Trên Máy Tính & Điện Thoại)": "How to Copy a YouTube Link (Desktop & Mobile)",
