    ", hoặc link có kèm giờ phát": ", or links with start timestamps",
    "Ghi chú Privacy-Enhanced:": "Privacy-Enhanced Note:",
    "Hệ thống phát video qua máy chủ rút gọn": "Videos play through the streamlined host",
    "giúp giảm tối đa giao diện gây phân tâm xung quanh (cột bình luận, đề xuất). Lưu ý nếu chủ kênh YouTube khóa quyền nhúng bên thứ 3 hoặc bạn mở web trực tiếp bằng giao thức": "to minimize distracting UI clutter around the player (comments, recommendations). Note: if the YouTube creator disables third-party embedding or you open the page directly via",
    ", khung Bước 2 sẽ hiện sẵn nút mở sang YouTube trong 1 chạm.": ", the Step 2 panel will provide a ready 1-tap button to open it on YouTube.",
