    "Chặn tự gõ câu lệnh mới; chỉ cần bấm chọn Prompt mẫu là xem trọn quy trình tổng hợp Prompt, Google Docs Diff, Đánh giá độc giả và Biểu đồ SVG Mode 5.": "Typing new prompts is locked; simply pick a sample Prompt to preview Prompt assembly, Google Docs Diff, Reader Review, and Mode 5 SVG Charts.",
