    "💡 Vì sao là \"Web Viết Tiểu Thuyết Của Bi\"? Tên gọi \"Bi\" chính là nickname ở nhà thân mật của tác giả Mai Hải Đăng — đặt tên như vậy để góc sáng tác luôn giữ cảm giác gần gũi như ở nhà mình vậy.": "💡 Why \"Bi's Novel Writing Studio\"? \"Bi\" is the affectionate family nickname of author Mai Hải Đăng — named so this creative corner always feels as warm and cozy as home.",
