    "▸ Chế Độ 5: Vẽ Biểu Đồ Cốt Truyện & Niên Biểu Dựa Theo Story Bible (Siêu Nhẹ, Chính Xác)": "▸ Mode 5: Plot & Timeline Diagram Generator Based on Story Bible (Ultra-Light, Accurate)",
