    "Xem Khung Story Bible Chính Thức Tab 4": "View Tab 4 Official Story Bible Box",
    "▾ Cẩm Nang Chống Quên Cho Truyện Dài Hàng Trăm Chương Cùng Google NotebookLM": "▾ Anti-Amnesia Guide for 100+ Chapter Novels with Google NotebookLM",
    "Đi tới Cẩm Nang NotebookLM Tab 4": "Go to Tab 4 NotebookLM Guide",
    "Khi tác phẩm của bạn đã vượt 15-30 chương trở lên hoặc khi bạn muốn tái tổng hợp một bộ Story Bible siêu chi tiết không sót bất kỳ manh mối nào từ đầu truyện.": "When your work exceeds 15–30 chapters or when you want to re-compile an ultra-detailed Story Bible without missing a single clue from the beginning.",
    "Vào Tab 4, nhìn thẻ nổi bật \"Mẹo Giữ Ký Ức Cho Truyện Dài Hàng Trăm Chương Với NotebookLM\".": "Open Tab 4 and locate the highlighted card \"Memory Tips for 100+ Chapter Novels with NotebookLM\".",
    "Bấm nút \"1. Tải PDF Gộp Toàn Bộ Chương\" để đóng gói tất cả từ Chương 1 -> Chương cuối thành 1 bản PDF.": "Click \"1. Download Merged All-Chapters PDF\" to bundle everything from Chapter 1 -> Final Chapter into 1 PDF.",
    "Bấm \"2. Mở Ngay Sổ Tay NotebookLM ↗\", tải PDF vừa xuất vào đó, rồi bấm \"3. Sao Chép Prompt Tổng Hợp Story Bible Chi Tiết\" dán vào NotebookLM — nhận lại toàn văn Story Bible chuẩn mực và dán ngược vào khung Tab 4.": "Click \"2. Open NotebookLM Now ↗\", upload the exported PDF, then click \"3. Copy Detailed Story Bible Synthesis Prompt\" and paste it into NotebookLM — then paste the resulting comprehensive Story Bible back into Tab 4.",
    "NotebookLM đọc cực khỏe hàng triệu chữ nguồn cùng lúc mà không bị trôi trí nhớ, cực kỳ phù hợp làm bộ nhớ dài hạn song song cùng Studio!": "NotebookLM effortlessly ingests millions of source words at once without memory drift, making it an ideal parallel long-term memory alongside Studio!",
