    "▾ Xuất File Word .DOCX Chuẩn OOXML ZIP Thực Thụ (Mở Mượt Trên Word & Google Docs)": "▾ Export True OOXML ZIP Standard Word .DOCX (Opens Smoothly in Word & Google Docs)",
    "Mở Hộp Thoại Xuất .DOCX / .PDF": "Open .DOCX / .PDF Export Dialog",
    "Khi cần tải bản thảo về máy để biên tập tiếp trong Microsoft Word, gửi cho biên tập viên nhà xuất bản hoặc tải lên Google Docs.": "When you need to download your manuscript for further editing in Microsoft Word, sending to a publisher's editor, or uploading to Google Docs.",
    "Mở Hộp thoại Xuất Sách (từ Tab 6 hoặc từ thanh Công cụ biên tập ở Tab 1 / Tab 2).": "Open the Export Book dialog (from Tab 6 or the editing toolbar in Tab 1 / Tab 2).",
    "Xác nhận 3 thông tin: Tên tác phẩm (gõ mới hoặc chọn từ danh sách đã lưu), Chương mấy (chọn từ Tab 2 hoặc toàn bộ), và Tên tác giả.": "Confirm 3 fields: Book Title (type new or pick from saved list), Chapters (select from Tab 2 or all), and Author Name.",
    "Bấm nút xanh \"Xuất File .DOCX\" — file tải về có phần đầu chuẩn ZIP mở mượt trực tiếp trên mọi bộ gõ văn phòng!": "Click the blue \"Export .DOCX File\" button — the downloaded file has a true ZIP header and opens smoothly in any office suite!",
    "Header trong file Word và PDF chỉ đặt canh giữa đúng Tên Tác Phẩm, Footer chỉ đếm số trang đơn giản chứ không chèn ngày giờ rườm rà.": "Word and PDF headers display only the centered Book Title, and footers show clean page numbers without cluttered timestamps.",
