    "Chỉ đạo AI: Sử dụng kỹ thuật Match Cut điện ảnh: Kết thúc cảnh trước bằng hình ảnh một vật thể (ví dụ: tàn thuốc đỏ rực, giọt nước mưa, vòng xoáy tách cà phê) và mở đầu cảnh này bằng một hình ảnh có hình dáng/chuyển động tương tự ở không gian mới. Ví dụ văn phong: * * * Vệt khói trắng mảnh mai từ đầu điếu thuốc vừa tắt ngấm trong căn phòng thẩm vấn dường như nối dài ra, hòa vào màn sương mù dày đặc đang bao phủ lấy bến cảng phía Đông lúc hai giờ sáng.": "AI Directive: Use the cinematic Match Cut technique: end the previous scene on an object image (e.g., a glowing cigarette ash, raindrop, swirling coffee cup) and open this scene with an image of similar shape or motion in the new setting. Style example: * * * The slender wisp of white smoke rising from the extinguished cigarette in the interrogation room seemed to stretch outward, dissolving into the thick fog blanketing the East Pier at two in the morning.",
    "e.g., Rooftop café": "e.g., Rooftop café",
    "Tùy chỉnh chỉ thị hệ thống (System Prompt) riêng biệt cho từng chế độ từ Chế độ 1 đến Chế độ 5. Tự động ghép nối vào Prompt Tổng Hợp!": "Customize separate System Prompts for each mode from Mode 1 to Mode 5. Automatically merged into the Compiled Prompt!",
    "✍️ Chế độ 1: Viết Bản Nháp Tiểu Thuyết (3.000 - 4.000+ từ)": "✍️ Mode 1: Novel Draft Writing (3,000 - 4,000+ words)",
    "🧭 Chế độ 2: Tham Mưu Cốt Truyện, Bẻ Lái & Gỡ Bí": "🧭 Mode 2: Plot Advisory, Twists & Unblocking",
