    "▶ Chế độ 5": "▶ Mode 5",
    "Viết tiếp ngay sau tiếng chuông ở cuối Chương 3: Trần Minh Khôi và Lệ Băng bước lên sàn gỗ gác chuông tối đen, phát hiện cuộn băng ghi âm nằm sau quả lắc đồng. Giữ đúng xưng hô Tôi/Anh - Cô, tuyệt đối không dùng các cụm sáo ngữ bị cấm và không để lộ bí mật vết sẹo cổ tay quá sớm.": "Continue right after the bell toll at the end of Chapter 3: Trần Minh Khôi and Lệ Băng step onto the pitch-dark wooden floor of the bell tower and discover an audio cassette behind the brass pendulum. Keep the I/He - She address consistent, strictly avoid all banned clichés, and do not reveal the wrist-scar secret too early.",
    "Viết một phân đoạn hồi tưởng ngắn (khoảng 300 từ) xen góc nhìn POV ngôi thứ ba theo Trần Minh Khôi khi nhớ về ánh lửa hắt lên mặt kính đồng hồ quả quýt bị vỡ, giữ nguyên bí mật về Giáo sư Hoàng cho chương sau.": "Write a short flashback segment (~300 words) from Trần Minh Khôi's third-person POV recalling firelight glinting off the cracked glass of the pocket watch, keeping the secret about Giáo sư Hoàng intact for the next chapter.",
    "✍️ [CHẾ ĐỘ 1 — VIẾT BẢN THẢO CHÍNH THỨC] Nhập diễn biến chương truyện, tâm lý nhân vật, bối cảnh không gian hoặc phân cảnh bạn muốn AI triển khai chi tiết (3.000 - 4.000+ từ) tại đây... Ví dụ gợi ý để viết sâu sắc, không tua nhanh: - Cảnh 1 (Mưa khuya ở sảnh ga): Nhân vật A giữ im lặng khi nhận phong thư nặc danh, miêu tả chậm cảm giác lạnh gáy, mùi nước mưa và ánh đèn vàng hắt lên ngón tay run. - Cảnh 2 (Đối thoại căng thẳng): Cuộc chạm trán với Nhân vật B, dùng lời nói ẩn ý chứ chưa vội lật bài ngửa ngay. - Lưu ý: Hệ thống tự động lồng ghép dàn ý đã phát triển ở Chế độ 2 (nếu có) + Story Bible + Mốc chuyển phân cảnh + Ma trận Ai Biết Gì.": "✍️ [MODE 1 — OFFICIAL DRAFT WRITING] Enter chapter events, character psychology, setting atmosphere, or scenes you want AI to expand in rich detail (3,000 - 4,000+ words) here... Example for deep, unhurried writing: - Scene 1 (Late-night rain in station hall): Character A stays silent upon receiving an anonymous envelope; slowly describe the chill down their neck, scent of rain, and amber light on trembling fingers. - Scene 2 (Tense dialogue): Confrontation with Character B using veiled subtext rather than revealing cards too soon. - Note: The system automatically integrates your Mode 2 outline (if any) + Story Bible + Scene Break markers + Who-Knows-What Matrix.",
    "✅ Duyệt & Chốt Bản Thảo — Tự Động Cập Nhật Story Bible": "✅ Approve & Finalize Draft — Auto-Update Story Bible",
    "Đã Duyệt": "Approved",
    "💡 Sau khi hoàn tất cập nhật Story Bible và chỉ mục chống quên, hệ thống sẽ thông báo thành công ngay trên màn hình (Không hiện cửa sổ đầu ra dư thừa tại đây vì đầu ra đã nằm ở Tab 3 và Story Bible ở Tab 4).": "💡 Once the Story Bible and anti-amnesia index update finishes, a success banner appears right on screen (no redundant output window is shown here since outputs live in Tab 3 and Story Bible in Tab 4).",
