    "Ngay khi tờ ảnh cũ rơi xuống mặt bàn, cái tên viết bằng mực đỏ phía sau lại chính là tên của [Nhân vật đáng tin nhất].": "As soon as the old photograph fell onto the table, the name written in red ink on the back turned out to be [Most Trusted Character].",
