    "Hắn chắc chắn mình đã khóa trái chiếc ngăn kéo lúc rời phòng — thế nhưng chiếc chìa khóa đồng lúc này lại nằm ngay trên gối.": "He was certain he had double-locked the drawer before leaving the room—yet the brass key was now lying right on his pillow.",
    "Câu hỏi bỏ lửng gây sởn gai ốc": "Chilling open-ended question",
    "- Cậu nghĩ suốt ba năm qua... người đang ngồi nói chuyện với cậu mỗi tối thực sự là ai? (Nhân vật B)": "\"Who do you think... has actually been sitting there talking to you every night for the past three years?\" (Character B)",
