    "Đồng hồ trên tháp chuông vừa điểm mười hai tiếng, và đúng lúc ấy toàn bộ đèn hành lang đồng loạt tắt phụt.": "The bell-tower clock had just struck twelve, and at that exact moment every hallway light snapped off at once.",
