    "Lưỡi dao không dừng lại ở cổ đối phương, mà quay ngược lại kề sát ngay động mạch của chính người vừa giải cứu cô.": "The blade did not stop at the enemy's throat—it whipped around and pressed right against the artery of the very person who had just rescued her.",
