    "Hãy cứ viết nháp thật thoải mái — hệ thống Tự Lưu 3 Tầng và Khiên Chống Reload sẽ giữ chữ giúp bạn.": "Draft freely with peace of mind — the 3-Tier Auto-Save and Anti-Reload Shield safeguard every word.",
