    "Gợi ý cho Chế độ 1:": "Tip for Mode 1:",
    "Bạn nên làm rõ bạn muốn AI viết mấy phân cảnh (Càng chia nhỏ càng tốt), mạch truyện nhanh hay chậm, mỗi phân cảnh bao nhiêu từ... Cơ bản như vậy cộng với cái story bible và cái cốt truyện có AI tư vấn bên cạnh nữa là mình thấy oke rồi đó bạn, mình cũng hay viết tới đó thôi hẹ hẹ": "Specify how many scenes you want the AI to write (the smaller the breakdown, the better), whether the pacing should be fast or slow, and how many words per scene... Basically that plus your Story Bible and the AI-guided plot outline alongside it is more than enough—that is usually how far I outline too haha.",
    "Gợi ý cho Chế độ 3:": "Tip for Mode 3:",
    "Bạn nên đọc bản thảo trước, rồi có nghi ngờ thì đưa AI review và kiểm tra lại": "Read through your draft yourself first, then send any suspect spots to the AI for review and double-checking.",
    "Gợi ý cho Chế độ 4:": "Tip for Mode 4:",
    "Thường thì mình sẽ để AI là:": "Usually I prompt the AI with:",
    "Bạn là 1 nhà phê bình tiểu thuyết, văn học mạng và chính quy 20 năm kinh nghiệm cho các nhà xuất bản lớn và phân tích cho tôi hướng đi cốt truyện đã tối ưu chưa, có thực sự lôi cuốn độc giả không, có chỗ nào cần cải thiện để giữ chân người đọc và khiến sức mạnh, tốc độ của cốt truyện không bị ảo quá không?": "Act as a veteran novel critic with 20 years of experience in both web fiction and traditional publishing at major houses. Analyze whether my plot direction is truly optimal and gripping for readers, where it needs improvement to retain readership, and how to keep the power scaling and pacing grounded instead of feeling overly contrived.",
    "Bạn có thể copy câu mình gợi ý bằng cách bấm vào gạch chân 1 phát là xong.": "You can copy my suggested prompt in one click by tapping the underlined text.",
    "Gợi ý cho Chế độ 5:": "Tip for Mode 5:",
    "Đơn giản thì bạn bấm nút chạy prompt, chọn mô hình xịn 1 tí :))": "Simply click the run prompt button and pick one of the stronger models :))",
    "📋 Đã copy câu lệnh gợi ý Chế độ 4! Hãy dán vào ô nhập lệnh bên dưới.": "📋 Copied Mode 4 suggested prompt! Paste it into the prompt box below.",
    "🎨 Chế độ 5 · Liên kết Story Bible + Vẽ Sơ đồ Cốt Truyện SVG & Biên Niên Sử Thời Gian": "🎨 Mode 5 · Linked with Story Bible + SVG Plot Diagram & Chronicle Timeline",
    "🎨 Chạy Vẽ Sơ Đồ Cốt Truyện SVG (Liên Kết Story Bible)": "🎨 Render SVG Plot Diagram (Linked to Story Bible)",
