    "✍️ Chế độ 1: Viết Bản Thảo Văn Học Chính Thức (Literary Drafting)": "✍️ Mode 1: Official Literary Manuscript Drafting",
    "Sáng tác văn xuôi tiểu thuyết hoàn chỉnh, giàu hình ảnh, cảm xúc chân thực, đối thoại sắc sảo và tuân thủ tuyệt đối Story Bible.": "Compose complete literary prose rich in sensory imagery, authentic emotion, sharp dialogue, and 100% Story Bible compliance.",
    "💡 Chế độ 2: Bàn Tròn Ý Tưởng & Thiết Kế Nhánh Cốt Truyện (Plot Brainstorming)": "💡 Mode 2: Idea Roundtable & Plot Branch Design",
    "Đề xuất các phương án phát triển tình tiết đột phá, nút thắt bất ngờ (plot twist), cách gỡ bí kịch bản và phương án thu hồi phục bút.": "Propose breakthrough plot paths, surprising plot twists, writer’s-block solutions, and foreshadowing payoff plans.",
    "🔍 Chế độ 3: Thanh Tra Logic, Mâu Thuẫn Thời Gian & Ma Trận Ai Biết Gì (Continuity Audit)": "🔍 Mode 3: Continuity, Timeline & Knowledge Matrix Auditor",
    "Rà soát nghiêm ngặt toàn bộ lỗ hổng logic, sai lệch dòng thời gian, nhân vật biết trước thông tin chưa được tiết lộ (OOC / Epistemic Leak) và phục bút bị bỏ quên.": "Strictly audit all plot holes, timeline mismatches, premature secret leaks (OOC / Epistemic Leak), and forgotten foreshadowing.",
    "✨ Chế độ 4: Biên Tập Chuyên Sâu, Gọt Văn Chống Sáo Rỗng & Chuẩn Hóa Thoại (Literary Polish)": "✨ Mode 4: Deep Literary Editing, Anti-Cliché & Dialogue Polish",
    "Nâng cấp chất lượng văn chương của bản thảo, loại bỏ 100% từ ngữ sáo rỗng (Anti-Cliché), chuẩn hóa định dạng hội thoại và làm giàu nhạc tính tiếng Việt.": "Elevate manuscript prose quality, eliminate 100% of clichés (Anti-Cliché), standardize dialogue formatting, and enrich rhythmic flow.",
    "🎨 Chế độ 5: Vẽ Biểu Đồ Cốt Truyện, Mạng Lưới Nhân Vật & Đối Chiếu Thời Gian (Visual Chronicle)": "🎨 Mode 5: Plot Graph, Character Web & Visual Chronology Audit",
    "Trích xuất cấu trúc sự kiện, mạng lưới quan hệ nhân vật và dòng thời gian thành sơ đồ trực quan kèm báo cáo đối chiếu xuyên chương.": "Extract event structures, character relationship webs, and timelines into visual diagrams with cross-chapter audit reports.",
    "🧪 KHUYÊN DÙNG #1 · SIÊU SUY LUẬN XHIGH — CÂN BẰNG TOÀN DIỆN GEMINI 4": "🧪 #1 RECOMMENDED · XHIGH REASONING — ALL-ROUND GEMINI 4 BALANCE",
    "⚡ Cân bằng Nhanh & Sâu (#1)": "⚡ Fast & Deep Balance (#1)",
    "Lựa chọn ưu tiên số 1 cho cả 5 chế độ: viết chương dài (Chế độ 1), tham mưu cốt truyện (Chế độ 2), kiểm toán mâu thuẫn (Chế độ 3), đánh giá độc giả (Chế độ 4) & vẽ biểu đồ (Chế độ 5).": "#1 priority choice across all 5 modes: long-form drafting (Mode 1), plot brainstorming (Mode 2), logic auditing (Mode 3), beta critique (Mode 4) & plot diagramming (Mode 5).",
    "🌟 DÒNG FLASH MƯỢT MÀ & GIÀU CẢM XÚC": "🌟 SMOOTH & EMOTIONAL FLASH SERIES",
    "⚡ Nhanh & Ổn định": "⚡ Fast & Steady",
    "Lựa chọn tối ưu nhất để viết bản thảo chính thức (Chế độ 1) và gọt văn (Chế độ 4). Văn phong có hồn, giàu ẩn dụ và không bị khô cứng.": "Optimal choice for official manuscript drafting (Mode 1) and literary polishing (Mode 4). Soulful prose rich in metaphor without stiffness.",
    "👑 CHUYÊN GIA LOGIC DÀI HƠI & PHỤC BÚT PHỨC TẠP": "👑 LONG-FORM LOGIC & INTRICATE FORESHADOWING SPECIALIST",
    "⏳ Trung bình (Suy luận sâu)": "⏳ Moderate (Deep reasoning)",
    "Rất mạnh khi viết các chương cao trào đan xen nhiều tuyến nhân vật, đấu trí phức tạp hoặc khi chạy Thanh tra Logic (Chế độ 3).": "Excels at multi-POV climax chapters, complex mind games, or running the Continuity Auditor (Mode 3).",
    "💎 ĐỈNH CAO VĂN CHƯƠNG & ĐỘC THOẠI NỘI TÂM": "💎 PINNACLE OF LITERARY PROSE & INNER MONOLOGUE",
