    "Lý tưởng cho những phân cảnh tâm lý nặng đô, hồi tưởng bi kịch hoặc chương kết quyển cần sức nặng văn học đặc biệt.": "Ideal for heavy psychological scenes, tragic flashbacks, or volume finales demanding exceptional literary weight.",
    "⚡ SIÊU NHANH — CHỈ NÊN DÙNG ĐỂ NHÁP NHANH / HỎI ĐÁP NGẮN": "⚡ ULTRA FAST — BEST FOR QUICK SKETCHES / SHORT Q&A ONLY",
    "🚀 Tức thì": "🚀 Instant",
    "⚠️ LƯU Ý: Mô hình Flash-Lite ưu tiên tốc độ nên văn phong dễ bị tóm tắt hoặc kém bay bổng. Khi viết tiểu thuyết chính thức, bạn nên đổi sang Gemini 3.8 Flash hoặc Gemini 3.1 Pro!": "⚠️ NOTE: Flash-Lite prioritizes speed so prose can sound summarized or flat. For official novel chapters, switch to Gemini 3.8 Flash or Gemini 3.1 Pro!",
    "Muốn viết sâu 20.000+ từ mỗi lần chạy với Gemini Argon 4 / Carbon 4?": "Want to write 20,000+ words deep per run with Gemini Argon 4 / Carbon 4?",
