    "21. Luồng Phát Trực Tiếp / PiP, Đồng Bộ Nền YouTube, Cỡ Chữ Toàn Web & Mục #5 Linh Tinh (v46)": "21. Seamless Streams / PiP, YouTube Background Sync, System Font Scale & Tab 6 Box #5 (v46)",
    "NATIVE PIP · BG VIDEO SYNC · SYSTEM FONT SCALE · CHỨC NĂNG LINH TINH": "NATIVE PIP · BG VIDEO SYNC · SYSTEM FONT SCALE · MISCELLANEOUS HUB",
    "Nâng cấp phát YouTube mượt mà trên cả Mobile & Desktop (Repeat/A-B không đen màn hình, đồng bộ phát/dừng/tua sang Background, System PiP), Cỡ Chữ Hệ Thống 4 mức & Mục #5 Chức Năng Linh Tinh + Chuỗi điểm danh!": "Upgraded YouTube playback across Mobile & Desktop (Repeat/A-B loop without black screen, instant play/pause/seek Background Sync, System PiP), 4-tier System Font Scale & Tab 6 Box #5 Miscellaneous Fun + Streak Badges!",
    "Khi bấm Lặp video (Repeat) hoặc Lặp đoạn A–B trên YouTube, trình phát giữ nguyên luồng đang chạy không bị đen hay gián đoạn; Video Background tự động khớp Tạm dừng / Phát tiếp / Tua theo khung chính.": "Toggling YouTube Repeat or A–B Loop keeps the active stream running seamlessly without blacking out, while the Background Video automatically mirrors Pause / Play / Seek from the main player.",
    "Đổi Cỡ Chữ Toàn Web (Nhỏ · Bình thường · To · Rất to) trực tiếp trên Thanh Header hoặc Tab 5/Tab 6; giữ chuỗi Điểm danh 7/21/90/365 ngày nhận huy hiệu Tiểu thuyết gia.": "Switch System Font Scale (Small · Normal · Large · Extra Large) right from the Header or Tab 5/Tab 6; maintain daily check-in streaks at 7/21/90/365 days to unlock Novelist Badges.",
    "Khám phá Ô #5 \"Chức năng linh tinh\" ở Tab 6 (giữa Ô 4 và Tải App) với SaLưới mini game, kỷ niệm đời đầu & chế độ đa ngôn ngữ đầy đủ kể cả khung Prompt và định dạng ngày giờ bản địa!": "Explore Tab 6’s Box #5 \"Miscellaneous Fun\" (between Card 4 and Install App) featuring the SaLưới mini-game, early supporter tributes, plus complete localization including Prompt Frames and native country date formats!",
    "Repeat / A–B Loop Mượt Mà & Đồng Bộ Nền YouTube (Mod 39/40)": "Seamless Repeat / A–B Loop & YouTube Background Sync (Mod 39/40)",
    "Bấm Lặp video hoặc Lặp đoạn A–B nay giữ nguyên khung phát không đen màn hình, đồng thời Video Background luôn Dừng/Chạy/Tua đồng bộ tức thì theo trình phát chính.": "Toggling video Repeat or A–B Loop now preserves the active viewport without blacking out, while Background Video pauses, plays, and seeks instantly alongside the main player.",
    "Cỡ Chữ Toàn Web (4 Mức) & Chuỗi Điểm Danh Huy Hiệu": "4-Tier System Font Scale & Daily Streak Badges",
    "Tùy chỉnh Cỡ chữ hệ thống (Nhỏ / Bình thường / To / Rất to) đồng bộ Header, Tab 5 & Tab 6; điểm danh giữ chuỗi 7, 21, 90 và 365 ngày để mở khóa các huy hiệu Tiểu thuyết gia.": "Customize System Font Scale (Small / Normal / Large / Extra Large) synced across Header, Tab 5 & Tab 6; hold 7, 21, 90, and 365-day streaks to unlock Novelist Badges.",
    "Mục #5 Chức Năng Linh Tinh & Đa Ngôn Ngữ Toàn Diện": "Tab 6 Box #5 Miscellaneous Hub & Complete Multi-Language Sync",
    "Khám phá Ô #5 Chức năng linh tinh ở Tab 6, video hướng dẫn tràn khung chuẩn Mobile/Desktop, cùng dịch đầy đủ 6 ngôn ngữ cho mọi thông báo, khung Prompt & ngày giờ bản địa!": "Explore Tab 6 Box #5 Miscellaneous Fun, full-viewport responsive tutorial video across Mobile & Desktop, and complete 6-language localization covering toasts, Prompt Frames & regional dates!",
    "v46.0 — Sửa Repeat/A–B Không Đen Video & Đồng Bộ Nền Chặt (Mod 39/40), Cỡ Chữ Toàn Web, Chuỗi Điểm Danh, Ô #5 Linh Tinh & Video Tràn Khung Mobile": "v46.0 — Zero-Blank Repeat/A–B & Tight Background Sync (Mod 39/40), System Font Scale, Streak Badges, Tab 6 Box #5 & Full-Frame Mobile Video",
    "Sửa triệt để YouTube Repeat/A–B & Đồng bộ Video Nền (Mod 39/40 + nativePlayer): Không phá hủy hay làm đen iframe khi bật Lặp toàn video / A–B; Video nền đồng bộ tức thì Tạm dừng / Phát / Tua theo cả iframe lẫn luồng HTML5 trực tiếp.": "Definitive fix for YouTube Repeat/A–B & Background Video Sync (Mod 39/40 + nativePlayer): Preserves live iframe without destroying or blacking out on Repeat / A–B Loop; Background Video mirrors Pause / Play / Seek instantaneously across both iframe and HTML5 streams.",
    "Video Hướng Dẫn Hiển Thị Trọn Khung Trên Mobile & Fullscreen (Mod 28 + Mod 33): Gỡ triệt để lỗi co góc trên-trái trên điện thoại dọc & cập nhật thêm Phân đoạn #21 (~10:22) bao phủ mọi tính năng mới.": "Full-Viewport Responsive Tutorial Video on Mobile & Fullscreen (Mod 28 + Mod 33): Eliminates top-left shrinking on portrait phones and adds Chapter #21 (~10:22) covering all new features.",
    "Cỡ Chữ Toàn Trang 4 Mức (Nhỏ -> Rất to), Mốc Huy Hiệu Điểm Danh (7/21/90/365 ngày) & Ô #5 Chức Năng Linh Tinh tại Tab 6 tối ưu responsive trên mọi kích thước màn hình.": "4-Level Page Font Scale (Small -> Extra Large), Daily Check-in Streak Milestones (7/21/90/365 days) & Tab 6 Card #5 Miscellaneous Fun Hub optimized responsively across every viewport size.",
    "Hoàn Thiện Đa Ngôn Ngữ 6 Thứ Tiếng (EN / 简体 / 繁體 / KO / JA / VI): Bao gồm cả Prompt Khung 5 Chế độ, thông báo góc thu/mở, thẻ trạng thái & định dạng ngày giờ thực tế từng quốc gia (YY/MM/DD, MM/DD/YY, dd/mm/yy).": "Complete 6-Language Localization (EN / 简体 / 繁體 / KO / JA / VI): Includes all 5-Mode Prompt Frames, corner collapse/expand toasts, status pills & authentic regional date formats (YY/MM/DD, MM/DD/YY, dd/mm/yy).",
    "Quá đỉnh luôn chứ sao không": "Absolutely top-notch, how could it not be!",
