    "Server Cloudflare Worker / Piped riêng (khuyên dùng trên điện thoại để bật PiP & nghe tắt màn hình 100%):": "Custom Cloudflare Worker / Piped server (recommended on mobile for 100% PiP & screen-off audio):",
