    "📺 Luồng phát công cộng phản hồi chậm — Đã chuyển dự phòng về Luồng phát YouTube (tự động tắt MP3 cũ ở Tab 3 để chờ đồng bộ).": "📺 Public Stream responded slowly — Switched fallback to YouTube Stream (old Tab 3 MP3 stopped automatically).",
