    "🔄 Luồng phát công cộng đang bị YouTube giới hạn — Hệ thống đang TỰ ĐỘNG kết nối lại liên tục đến khi phát nền được!": "🔄 Public Stream is currently restricted by YouTube — Auto-reconnecting continuously until background audio succeeds!",
