    "Nếu các server công cộng tạm bị YouTube giới hạn, bạn có thể tạo Cloudflare Worker miễn phí, dán code có sẵn rồi nhập URL *.workers.dev vào ô dưới đây:": "If public servers are temporarily rate-limited by YouTube, deploy a free Cloudflare Worker with the built-in template and paste your *.workers.dev URL below:",
