    "🎬 CHỈ THỊ HỢP NHẤT CHẾ ĐỘ 1 × STORY BIBLE × MỐC PHÂN CẢNH / POV": "🎬 MODE 1 × STORY BIBLE × SCENE MARKERS / POV INTEGRATION DIRECTIVE",
    "🎬 CHỈ THỊ HỢP NHẤT CHẾ ĐỘ 2 × STORY BIBLE × MỐC PHÂN CẢNH / POV": "🎬 MODE 2 × STORY BIBLE × SCENE MARKERS / POV INTEGRATION DIRECTIVE",
    "• Giữ chặt máy quay đúng góc nhìn POV trên xuyên suốt toàn phân cảnh (không head-hopping).": "• Keep the narrative camera strictly locked on the POV above throughout the entire scene (zero head-hopping).",
    "🎬 LIÊN KẾT MẠCH CHUYỂN CẢNH TỪ CHƯƠNG LIỀN TRƯỚC:": "🎬 SEAMLESS TRANSITION BRIDGE FROM PREVIOUS CHAPTER:",
    "Đoạn kết ngay trước chương này để AI nối mạch không gian/cảm xúc mượt mà:": "Closing passage immediately preceding this chapter for smooth spatial and emotional continuity:",
    "🎬 SƠ ĐỒ PHÂN CẢNH & CHỐT GÓC NHÌN POV BẮT BUỘC (SCENE MARKERS):": "🎬 MANDATORY SCENE MARKERS & POV CAMERA BLUEPRINT:",
    "YÊU CẦU TỐI THƯỢNG: Tác phẩm PHẢI đi qua lần lượt từng phân cảnh dưới đây,": "SUPREME REQUIREMENT: The chapter MUST progress sequentially through each scene below,",
    "ngăn cách giữa các phân cảnh bằng dấu `* * *`, giữ chặt máy quay đúng POV!": "separated between scenes by `* * *`, keeping the camera strictly locked to each POV!",
