    "⚠️ RÀNG BUỘC LIÊN TỤC VẬT PHẨM & THƯƠNG TÍCH GIỮA CÁC CẢNH:": "⚠️ CROSS-SCENE PROP & INJURY CONTINUITY CONSTRAINTS:",
    "🧭 DIỄN BIẾN & DÀN Ý CỐT TRUYỆN ĐÃ PHÁT TRIỂN Ở CHẾ ĐỘ 2 (LỒNG GHÉP SÂU)": "🧭 MODE 2 DEVELOPED PLOT & OUTLINE ARCHIVE (DEEP INTEGRATION)",
    "Hãy lồng ghép khéo léo và triển khai chậm rãi, giàu chiều sâu tâm lý theo diễn biến cốt truyện từ Chế độ 2 dưới đây kết hợp hài hòa với Story Bible, Mốc chuyển phân cảnh và Câu lệnh bên dưới (tuyệt đối không tua nhanh sự kiện):": "Weave in skillfully and unspool slowly with rich psychological depth following the Mode 2 plot below, harmonizing with the Story Bible, Scene Markers, and Author Command (never rush events):",
    "🛡️ KIỂM ĐỊNH LOGIC, NHẬN THỨC NHÂN VẬT & PHỤC BÚT TRƯỚC KHI VIẾT": "🛡️ PRE-FLIGHT LOGIC, EPISTEMIC & FORESHADOWING GUARDRAILS",
    "• Tuân thủ đầy đủ hồ sơ nhân vật và bối cảnh trong Story Bible.": "• Strictly honor all character profiles and setting details in the Story Bible.",
    "🔗 NGỮ CẢNH KÝ ỨC CỤC BỘ (BM25 RAG) & ĐOẠN NỐI MẠCH CHƯƠNG HIỆN TẠI": "🔗 LOCAL BM25 RAG MEMORY & CURRENT CHAPTER CONTINUATION CONTEXT",
    "[CHI TIẾT KÝ ỨC CỤC BỘ TRÍCH XUẤT THEO NGỮ CẢNH (BM25 RAG)]:": "[CONTEXTUALLY RETRIEVED LOCAL MEMORY PASSAGES (BM25 RAG)]:",
