    "(Chương hiện tại đang trống — Hãy bắt đầu viết từ câu mở đầu chương)": "(Current chapter is empty — start writing from the chapter opening sentence)",
    "✍️ YÊU CẦU / CÂU LỆNH SÁNG TÁC CỤ THỂ CỦA TÁC GIẢ CHO CHƯƠNG NÀY": "✍️ AUTHOR'S SPECIFIC SCENE COMMAND / WRITING BRIEF FOR THIS CHAPTER",
    "🚀 CHỈ THỊ BẮT ĐẦU: Hãy thực thi ngay yêu cầu trên với chất lượng văn học cao nhất, tuân thủ 100% Story Bible, Mốc chuyển phân cảnh và Ma trận Ai Biết Gì!": "🚀 LAUNCH DIRECTIVE: Execute the brief above immediately at peak literary quality, adhering 100% to the Story Bible, Scene Markers, and Epistemic Matrix!",
    "=== [CHẾ ĐỘ 2 ĐỘC LẬP: THAM MƯU CỐT TRUYỆN & PHÁT TRIỂN DIỄN BIẾN] ===": "=== [STANDALONE MODE 2: PLOT STRATEGY & ARC DEVELOPMENT] ===",
    "[QUY TẮC & VAI TRÒ TỪ NGƯỜI DÙNG]:": "[SYSTEM ROLE & AUTHOR GUIDELINES]:",
    "[STORY BIBLE CHÍNH THỨC CẦN BÁM SÁT & ĐỐI CHIẾU]:": "[OFFICIAL STORY BIBLE TO FOLLOW & CROSS-CHECK]:",
