    "Hãy phát triển 3 phương án diễn biến chi tiết cho chương tiếp theo khớp với Story Bible bên trên (triển khai chậm rãi, gài phục bút, không tua nhanh sự kiện).": "Develop 3 detailed plot paths for the next chapter aligned with the Story Bible above (steady pacing, plant subtle foreshadowing, never rush events).",
    "Hãy trả lời trực tiếp thành bản tham mưu rõ ràng để tác giả chọn đưa vào Chế độ 1 viết tiểu thuyết.": "Respond directly with a structured strategic brief ready for the author to pick and send into Mode 1 drafting.",
    "=== [CHẾ ĐỘ 3 ĐỘC LẬP: KIỂM TOÁN LOGIC & MA TRẬN AI BIẾT GÌ] ===": "=== [STANDALONE MODE 3: LOGIC AUDIT & EPISTEMIC MATRIX CHECK] ===",
